async def test_aiohttp_execute_incremental_non_incremental_response(
    incremental_multipart_server,
):
    """If the server does not support the incremental delivery it can
    answer with a regular application/json response."""
    from aiohttp import web
    from gql.transport.aiohttp import AIOHTTPTransport

    async def json_handler(request):
        return web.json_response({"data": {"hero": {"name": "Luke"}}})

    app = web.Application()
    app.router.add_route("POST", "/", json_handler)
    server = await incremental_multipart_server([])
    # Use a dedicated server for the JSON response
    server.stop()
    await server.shutdown()

    from aiohttp.test_utils import TestServer

    json_server = TestServer(app)
    await json_server.start_server()

    url = json_server.make_url("/")
    transport = AIOHTTPTransport(url=url)

    async with Client(transport=transport) as session:
        results = []
        async for result in session.execute_incremental(
            gql("query { hero { name } }")
        ):
            results.append(result)

    await json_server.close()

    assert len(results) == 1
    assert results[0].data == {"hero": {"name": "Luke"}}
    assert results[0].has_next is False


