def make_incremental_server_messages(query_id: int) -> List[str]:
    """Format the incremental server answers as json messages."""
    return [
        json.dumps(
            {
                "type": answer["type"],
                "id": answer["id"].format(query_id=query_id),
                "payload": answer["payload"],
            }
        )
        for answer in incremental_server_answers
    ]


@pytest.mark.websockets
@pytest.mark.parametrize("graphqlws_server", [make_incremental_server_messages], indirect=True)
@pytest.mark.asyncio
async def test_websocket_execute_incremental(client_and_graphqlws_server):
    """The websocket transport forwards the incremental payloads
    through the existing graphql-ws protocol."""
    session, server = client_and_graphqlws_server

    # The default server handler sends one answer per received message and
    # then sends a complete message. We need to send one "subscribe" message
    # and receive all the payloads.
    results = []
    async for result in session.execute_incremental(
        gql("query Hero { hero { name } }")
    ):
        results.append(result)

    assert len(results) == 4
    assert results[0].data == {"hero": {"name": "R2-D2"}}
    assert results[0].has_next is True
    assert results[0].extensions == {"stage": 1}
    assert results[1].data == {
        "hero": {"name": "R2-D2", "primaryFunction": "Astrometrics"}
    }
    assert results[1].extensions == {"stage": 2}
    assert results[2].data == {
        "hero": {
            "name": "R2-D2",
            "primaryFunction": "Astrometrics",
            "appearsIn": ["EP4", "EP5"],
        }
    }
    assert results[3].has_next is False
    assert results[3].extensions is None


