@pytest.mark.asyncio
async def test_aiohttp_execute_incremental_defer(incremental_multipart_server):
    from gql.transport.aiohttp import AIOHTTPTransport

    def assert_request_headers(request):
        # Verify the Accept header follows the incremental delivery spec
        accept_header = request.headers["accept"]
        assert "multipart/mixed" in accept_header
        assert "boundary=graphql" in accept_header
        assert "deferSpec=20220824" in accept_header

    parts = create_defer_multipart_parts()
    server = await incremental_multipart_server(
        parts, request_handler=assert_request_headers
    )
    url = server.make_url("/")
    transport = AIOHTTPTransport(url=url)

    query = gql("query Hero { hero { name } }")

    async with Client(transport=transport) as session:
        results = []
        async for result in session.execute_incremental(query):
            results.append(result)

    assert len(results) == 4
    assert results[0].data == {"hero": {"name": "R2-D2"}}
    assert results[0].has_next is True
    assert results[1].data == {
        "hero": {"name": "R2-D2", "primaryFunction": "Astrometrics"}
    }
    assert results[2].data == {
        "hero": {
            "name": "R2-D2",
            "primaryFunction": "Astrometrics",
            "appearsIn": ["EP4", "EP5"],
        }
    }
    assert results[3].has_next is False
    assert results[3].data == results[2].data


